import{_ as a,o as t,c as i,a3 as s}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Build, Validate and Publish","description":"Prepare and validate ATLAS plugin packages and repository catalogs.","frontmatter":{"title":"Build, Validate and Publish","description":"Prepare and validate ATLAS plugin packages and repository catalogs."},"headers":[],"relativePath":"en/projects/atlas-plugins/developers/publishing.md","filePath":"en/projects/atlas-plugins/developers/publishing.md","lastUpdated":1793126673000}'),n={name:"en/projects/atlas-plugins/developers/publishing.md"};function l(r,e,o,d,p,c){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="build-validate-and-publish" tabindex="-1">Build, Validate and Publish <a class="header-anchor" href="#build-validate-and-publish" aria-label="Permalink to &quot;Build, Validate and Publish&quot;">​</a></h1><p>The <a href="./../plugin-template">Plugin Template</a> automates repeatable steps for a plugin&#39;s GitHub repository.</p><h2 id="build-the-package-and-catalog" tabindex="-1">Build the package and catalog <a class="header-anchor" href="#build-the-package-and-catalog" aria-label="Permalink to &quot;Build the package and catalog&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The build creates an installable package from the manifest and synchronizes the plugin entry in <code>repository.json</code>. Checks validate IDs, package paths and metadata in the generated package. A GitHub Actions workflow runs the build and checks on pushes and pull requests.</p><h2 id="release-steps" tabindex="-1">Release steps <a class="header-anchor" href="#release-steps" aria-label="Permalink to &quot;Release steps&quot;">​</a></h2><p>Follow the <a href="./compatibility">version and compatibility rules</a>, including backups, migration boundaries and recovery.</p><ol><li>Increment the manifest <code>version</code> for every functional or visible release.</li><li>Run <code>npm run build</code> and <code>npm run check</code>.</li><li>Confirm the manifest, catalog and generated package use the same ID and version.</li><li>Review package files, asset paths, external requests and declared capabilities.</li><li>Publish the catalog by pushing to <code>main</code>: <code>https://raw.githubusercontent.com/&lt;owner&gt;/&lt;repo&gt;/main/repository.json</code>. GitHub Pages is not required for the raw file; optionally enable it to publish <code>install.html</code>.</li><li>Add the catalog URL in ATLAS Administration and test the preview and package installation.</li></ol><p>Keep the plugin ID stable after the first publication. Large binary assets do not belong in the text-based package format; host them separately and reference them by URL.</p><h2 id="installation-status" tabindex="-1">Installation status <a class="header-anchor" href="#installation-status" aria-label="Permalink to &quot;Installation status&quot;">​</a></h2><p>The App server installs validated repository and imported packages in persistent plugin storage and serves static web files under <code>/plugin-assets/&lt;slug&gt;/</code>. Opening them runs their JavaScript in the browser; arbitrary Node modules or Runtime hooks are not automatically registered. Installation is not a sandbox: review package contents and browser code before opening. Building a package alone does not replace runtime or security testing.</p>`,11)])])}const g=a(n,[["render",l]]);export{u as __pageData,g as default};
